import time
import logging
from six import string_types
from datetime import datetime, timedelta
from moler.device import DeviceFactory
from taf.rfrl.bts.connections import device_aliases as connection_names
from taf.rfrl.bts.devices.exceptions import FileNotFound, SystemCheckFailure
from taf.rfrl.utilities.tl_config import load_moler_configuration_from_tl


def verify_if_latest_pm_file_exists():
    """
    Check if an appropriate PM file, generated in latest PM interval is present in /ram directory
    """
    current_time = datetime.now()
    logging.info("Current time: {}".format(current_time))
    logging.info("Waiting for file generation...")
    time.sleep(60)
    ls_output = _get_pm_files_list()
    files_names = ls_output["files"].keys()
    logging.info("Files names: {} \n Length: {}".format(files_names, len(files_names)))
    date_from_pm_file_name, pm_file_creation_date = _parse_time_from_ls_command(ls_output, file_index=-1)
    if date_from_pm_file_name.hour == pm_file_creation_date.hour == current_time.hour \
            and date_from_pm_file_name.minute == pm_file_creation_date.minute == current_time.minute:
        logging.info("PM file was successfully created")
    else:
        raise FileNotFound("Appropriate PM file was not found in the /ram directory. Current time: {}; "
                           "Time from filename: {}; Creation time: {}".format(current_time, date_from_pm_file_name,
                                                                              pm_file_creation_date))


def verify_if_pm_files_from_latest_24_hours_exist(interval=15, time_since_last_swupdate=None):
    """
    Check if PM files, generated in last 24 hours with an appropriate interval are present in /ram directory
    :param interval: interval between PM files generation [minutes]
    :param time_since_last_swupdate: time in seconds passed since latest swupdate
    """
    interval = ''.join(x for x in interval if x.isdigit())
    ls_output = _get_pm_files_list()
    files_names = ls_output["files"].keys()
    logging.info("Files names: {} \nNumber of files: {}".format(files_names, len(files_names)))
    swupdate_hours = time_since_last_swupdate / 3600
    if swupdate_hours > 24:
        if len(files_names) != 24 * (60 / int(interval)):
            raise FileNotFound("PM files from 24 hours was not found in the /ram directory")
    else:
        raise SystemCheckFailure("Test should have been run after 24 hours past first PM measurement collection!")


def convert_to_percentage_value(value):
    """
    Convert decimal value to percentage value e.g. 0.5 to 50%
    :param value: decimal value as a number or string
    :return: percentage value as string
    """
    if isinstance(value, string_types):
        value = float(value)
    return str(value * 100)


@load_moler_configuration_from_tl()
def _get_pm_files_list(bts_id=0, du_id=0):
    """
    Execute and return output of ls command.
    :param bts_id:  BTS id - related to Test Line configuration.
    :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
    :return: output of uptime command
    """
    gnb = DeviceFactory.get_device(name=connection_names.ssh_bts_du.format('GNB', bts_id, du_id))
    gnb.goto_state("FCT")
    ls_cmd = gnb.get_cmd(cmd_name="ls",
                         cmd_params={'options': '-lc', 'path': "/ram/ --time-style=full-iso | grep 'PM.BTS.*xml.gz'"})
    ls_output = ls_cmd()
    return ls_output


@load_moler_configuration_from_tl()
def _get_gnb_uptime(bts_id=0, du_id=0):
    """
    Execute and return output of uptime command.
    :param bts_id:  BTS id - related to Test Line configuration.
    :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
    :return: output of uptime command
    """
    gnb = DeviceFactory.get_device(name=connection_names.ssh_bts_du.format('GNB', bts_id, du_id))
    gnb.goto_state("FCT")
    uptime_cmd = gnb.get_cmd(cmd_name="uptime")
    uptime_output = uptime_cmd()
    return uptime_output


def _parse_time_from_ls_command(ls_output, file_index):
    """
    Parse time from ls command from string to time object.
    Include timezone information in file creation date and date placed in PM file name.
    :param ls_output: output of ls command
    :param file_index: index of the chosen PM file: 0 is the oldest one
    :return: the date obtained from file name, and creation date
    """
    try:
        pm_file_creation_date = list(ls_output["files"].values())[file_index].get('date')
        pm_file_name = list(ls_output["files"].values())[file_index].get('name')
        date_from_pm_file_name = datetime.strptime('.'.join(pm_file_name.split('.')[2:4])[:-2], '%Y%m%d.%H%M')
        logging.info("The chosen file: {} was created at {}".format(pm_file_name, pm_file_creation_date))
        timezone = int(pm_file_creation_date[-5:][:-2])
        pm_file_creation_date_time_obj = datetime.strptime(pm_file_creation_date[:-9], '%Y-%m-%d %H:%M:%S.%f')
        logging.info("The file creation date is {} timezone: {}".format(pm_file_creation_date_time_obj, timezone))
        timezone_diff = timedelta(hours=timezone)
        date_from_pm_file_name_with_timezone = date_from_pm_file_name + timezone_diff
        logging.info("A date from file name with timezone included is {}".format(date_from_pm_file_name_with_timezone))
        return date_from_pm_file_name_with_timezone, pm_file_creation_date_time_obj
    except IndexError:
        raise IndexError("Index {} is out of bound of {} elements PM files list! "
                         "Please set index properly!".format(file_index, len(ls_output["files"])))
